// THE HOST: a machine player 2's SCREEN CLEAR caught on his screen; cleared exactly as the host's own pulse clears one, credited to nobody
function pwrPulseTake(peer,m){   // v16.xx (cloud-coop-p2-screen-clear), CLOUD HUNT 2026-10-15: the host side of player 2 screen clear
  var e, K={crawler:1,snitch:1,sentry:1,listener:1,howler:1,bulwark:1};
  if(!peer||peer.state!=='in'||peer.seat<1||NET.role!=='host') return 'ignored';
  if(!netEntsHost()) return 'down';
  e=(NET.entMap&&NET.entMap[m.id|0])||null;
  if(!e||G.ents.indexOf(e)<0) return 'gone';
  if(!K[e.kind]||!(e.hp>0)||e.boss||e.elite||e.downed||e.finished||e.neutral||e.merc) return 'bad';
  e.hp=0; e.byPlayer=false; e.bySeat=0; e.hitT=0.2;
  return 'pulse';
}
