{v:'VER',what:'cloud-coop-p2-screen-clear: player 2 SCREEN CLEAR sends the host a pz word per machine (no 9999 shot), pays his medal, leaves his air strike meter alone, and the host clears those machines as its own pulse does, credited to nobody',
 run:function(){
   if(!(window.__state&&window.__endRaid&&window.__runPrep&&window.__topClear)) return 'SKIP: no raid here';
   if(typeof arcadeDeploy!=='function'||typeof pwrPulse!=='function'||typeof netOnMsg0!=='function'||typeof netEntsInit!=='function'||typeof airS!=='function') return 'SKIP: no arcade, screen clear or party in this fixture';
   var bad=[], g=null, p=null, NK={}, k, oSF=netSendFast, oS=netSend, oB=netBroadcast, oM=styMedal, rs=say, staged=false, moved=false, sent=[], med=0, h={seat:0,state:'in'}, hp={seat:1,state:'in'}, A=null, air0=0, i, e, c3=[], n, pz, sh, kl;
   try{
     __topClear(); __runPrep();
     if(!arcadeDeploy({mapIx:0,seed:4242})) return 'SKIP: no arcade raid';
     g=__state(); if(!g||g.over||!g.player) return 'SKIP: no live raid';
     p=g.player; p.iv=99; p.armor=0;
     say=function(){};
     for(k in NET) NK[k]=NET[k];
     staged=true;
     NET.on=true; NET.max=4; NET.specG=null; NET.up=[]; NET.upSeed=g.seed>>>0; NET.role='host'; NET.seat=0; NET.peers=[hp];
     netSendFast=function(q,m){ sent.push(JSON.parse(JSON.stringify(m))); return true; };
     netSend=function(q,m){ sent.push(JSON.parse(JSON.stringify(m))); return true; };
     netBroadcast=function(m){ sent.push(JSON.parse(JSON.stringify(m))); return 1; };
     styMedal=function(){ med++; };
     netEntsInit(g);
     for(i=0;i<g.ents.length;i++) g.ents[i].x+=20000;
     moved=true;
     for(i=0;i<g.ents.length&&c3.length<3;i++){ e=g.ents[i]; if(e.kind==='crawler'&&!e.elite&&!e.boss&&!e.downed&&e.hp>0&&e.nid){ e.x=p.x+60+c3.length*30; e.y=p.y+40; c3.push(e); } }
     if(c3.length<3) return 'SKIP: fewer than 3 plain crawlers in this raid';
     VX=p.x-W/2/ZOOM(); VY=p.y-H/2/ZOOM();
     // player 2 window fires the screen clear
     NET.role='join'; NET.seat=1; NET.peers=[h];
     A=airS(); air0=A.m||0; sent.length=0; med=0;
     n=pwrPulse(p);
     pz=sent.filter(function(m){ return m.t==='pz'; }); sh=sent.filter(function(m){ return m.t==='shot'; });
     if(n!==3) bad.push('his pulse hit '+n+' machines, not 3');
     if(pz.length!==3) bad.push('he sent '+pz.length+' pz words, not 3');
     if(sh.length) bad.push('he still sent '+sh.length+' shot words (dmg '+sh.map(function(m){return m.dmg;}).join(',')+')');
     if(med!==1) bad.push('his SCREEN CLEAR medal was paid '+med+' times, not once');
     if((A.m||0)!==air0) bad.push('his dead pulse charged his air strike meter '+air0+' to '+(A.m||0));
     // the host takes his words
     NET.role='host'; NET.seat=0; NET.peers=[hp];
     for(i=0;i<pz.length;i++) netOnMsg0(hp,JSON.stringify(pz[i]));
     for(i=0;i<c3.length;i++){ e=c3[i]; if(e.hp!==0||e.byPlayer!==false||e.bySeat!==0) bad.push('machine '+i+' after the host took it: hp '+e.hp+' byPlayer '+e.byPlayer+' bySeat '+e.bySeat); }
     sent.length=0; netEntsTick();
     kl=sent.filter(function(m){ return m.t==='kill'; });
     if(kl.length) bad.push('the host sent '+kl.length+' kill words for a screen clear credited to nobody');
   }catch(x){ bad.push('threw: '+(x&&x.message||x)); }
   finally{
     styMedal=oM; say=rs; netSendFast=oSF; netSend=oS; netBroadcast=oB;
     if(A) A.m=air0;
     if(moved&&g) for(i=0;i<g.ents.length;i++) g.ents[i].x-=20000;
     if(staged){ for(k in NET) if(!(k in NK)) delete NET[k]; for(k in NK) NET[k]=NK[k]; }
     try{ if(typeof ARCADE==='object'&&ARCADE.on) arcadeLeave(); }catch(_l){}
     try{ if(__state()&&!__state().over) __endRaid('abandon'); }catch(_e){}
     try{ __topClear(); }catch(_t){}
   }
   return bad.length?bad.join('; '):null;
 }},
